def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    if n == 0:
        return 1

    # Remove duplicates from banned
    banned = list(set(banned))

    # Build Aho-Corasick automaton
    # Each node: {char: next_node_idx}, fail_link, is_bad
    trie = [{}]
    is_bad = [False]

    for word in banned:
        curr = 0
        for ch in word:
            if ch not in trie[curr]:
                trie[curr][ch] = len(trie)
                trie.append({})
                is_bad.append(False)
            curr = trie[curr][ch]
        is_bad[curr] = True

    from collections import deque

    fail = [0] * len(trie)
    queue = deque()

    for ch, nxt in trie[0].items():
        queue.append(nxt)

    while queue:
        curr = queue.popleft()
        if is_bad[fail[curr]]:
            is_bad[curr] = True

        for ch, nxt in trie[curr].items():
            f = fail[curr]
            while f > 0 and ch not in trie[f]:
                f = fail[f]
            if ch in trie[f]:
                fail[nxt] = trie[f][ch]
            else:
                fail[nxt] = 0
            queue.append(nxt)

    def get_next(u: int, ch: str) -> int:
        while u > 0 and ch not in trie[u]:
            u = fail[u]
        return trie[u].get(ch, 0)

    # Filter out bad states
    valid_states = [i for i in range(len(trie)) if not is_bad[i]]
    if 0 in is_bad:  # Should not happen since banned strings are non-empty
        return 0

    state_map = {st: idx for idx, st in enumerate(valid_states)}
    m = len(valid_states)

    # Transition matrix: T[v][u] = number of transitions from u to v
    # where valid state vector v_{step+1} = T * v_{step}
    T = [[0] * m for _ in range(m)]
    chars = sorted(list(set(alphabet)))

    for u in valid_states:
        u_idx = state_map[u]
        for ch in chars:
            nxt = get_next(u, ch)
            if not is_bad[nxt]:
                v_idx = state_map[nxt]
                T[v_idx][u_idx] += 1

    def mat_mul(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k]:
                    for j in range(size):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(mat: list[list[int]], p: int) -> list[list[int]]:
        size = len(mat)
        res = [[int(i == j) for j in range(size)] for i in range(size)]
        base = mat
        while p > 0:
            if p & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p >>= 1
        return res

    T_pow = mat_pow(T, n)

    # Initial state vector has 1 at state_map[0], 0 elsewhere
    # So we sum T_pow[i][state_map[0]] for all i
    start_idx = state_map[0]
    ans = sum(T_pow[i][start_idx] for i in range(m)) % MOD
    return ans
